contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test: attempt a deposit of amount == MinDeposit and assert balance unchanged
    function run(uint64 sendAmount) public payable {
        // require we have enough ether provided by the caller to forward
        require(msg.value >= sendAmount, "insufficient funding");

        // read MinDeposit from contract
        uint min = c.MinDeposit();

        // we target the boundary case: use the provided sendAmount to equal min
        require(sendAmount == min, "sendAmount must equal MinDeposit");

        // record prior balance observed via public getter
        uint before = c.balances(address(this));

        // perform the deposit attempt forwarding ETH
        c.Deposit{value: sendAmount}();

        // read after balance
        uint after = c.balances(address(this));

        // on original P, sending exactly MinDeposit does NOT increase balance; mutant M allows it
        assert(after == before);
    }

    // allow contract to receive forwarded ETH to fund test calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount is the ETH sent to Deposit; caller is this contract
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // call Deposit with provided amount
        c.Deposit{value: amount}();
        // After the call, the contract's public balances getter for this contract
        // should only increase if amount > MinDeposit. We cannot read MinDeposit directly
        // (it's public, so we can), so check: if amount == c.MinDeposit() then balance stays 0
        // (i.e., not increased by that deposit). This captures the boundary difference.
        uint bal = c.balances(address(this));
        // General rule: if amount is exactly MinDeposit then balance must be zero (original behavior)
        assert(!(amount == c.MinDeposit()) || bal == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: caller must have enough balance to send 'amt'
    // We take amt and callerAddr as parameters. The test contract will send the ether.
    function runTest(uint amt, address depositor) public payable {
        // preconditions: deposit amount must be greater than MinDeposit
        uint min = c.MinDeposit();
        require(amt > min, "amt must be > MinDeposit");
        // ensure this contract holds the ether to forward
        require(msg.value == amt, "must forward amt as msg.value");
        // Call Deposit as this contract to deposit amt into c
        c.Deposit{value: amt}();
        // Observe recorded balance for this contract
        uint recorded = c.balances(address(this));
        // The property: recorded increase equals the actual amount sent
        assert(recorded == amt);
    }

    // allow fund reception so test caller can send ETH to this contract before invoking runTest
    receive() external payable {}
}

