contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // depositAmount is the Ether to send; prev is observed before calling Deposit
    function run(uint depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);
        // read previous balance via public getter
        uint prev = c.balances(address(this));
        // ensure we hit the branch that requires msg.value > MinDeposit
        uint minDep = c.MinDeposit();
        require(depositAmount > minDep);
        // perform the deposit, sending Ether
        c.Deposit{value: depositAmount}();
        // observe new balance
        uint after = c.balances(address(this));
        // The original contract should record the full sent amount; mutant caps to MinDeposit and will violate this
        assert(after == prev + depositAmount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address who, uint amount) public payable {
        require(amount > 0 && address(this).balance >= amount);
        // precondition: caller will send more than MinDeposit so that Deposit's if-branch executes
        // we must read MinDeposit via its public getter
        uint minDep = c.MinDeposit();
        require(amount > minDep);
        // record balance before
        uint before = c.balances(who);
        // perform deposit from this contract to affect balances(who)
        // the contract C uses msg.sender for balances, so to affect 'who' we need this contract to be 'who'
        // ensure that the 'who' parameter equals address(this)
        require(who == address(this));
        c.Deposit{value: amount}();
        uint after = c.balances(who);
        // general rule: after == before + amount
        assert(after == before + amount);
    }
    receive() external payable {}
}

