pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: depositor address and deposit amount and cashout amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 cashAmt) public {
        // admissible domain: deposit must be > MinDeposit to take effect in Deposit()
        uint256 Min = c.MinDeposit();
        // avoid trivial zero address depositor to ensure vm.prank works consistently
        vm.assume(depositor != address(0));
        vm.assume(depositAmt > Min);
        // bound cashAmt to a reasonable range so the fuzzer explores useful cases
        cashAmt = bound(cashAmt, 0, depositAmt);

        // fund depositor and perform Deposit() as depositor
        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // record balance before cashout via public getter
        uint256 before = c.balances(depositor);

        // perform CashOut as depositor for cashAmt
        vm.prank(depositor);
        bool ok;
        try c.CashOut(cashAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // after call, read balance for depositor
        uint256 after = c.balances(depositor);

        // General rule: if Deposit accepted (depositAmt>Min) and CashOut succeeded,
        // then after == before - cashAmt. The reference satisfies this for all inputs;
        // the mutant that adds only MinDeposit to balances will violate it for some inputs.
        if (ok) {
            assertTrue(after == before - cashAmt);
        } else {
            // If CashOut reverted/failed, then contract state must be unchanged for depositor
            // i.e., after == before. This also holds for the reference implementation.
            assertTrue(after == before);
        }
    }
}

