import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 cashOutAmt) public {
        // admissible bounds: deposit must be > MinDeposit to trigger deposit branch
        // MinDeposit is 1 ether in reference; keep wide but ensure deposit > 0
        vm.assume(depositAmount > 0);

        // fund depositor so they can send depositAmount
        vm.deal(depositor, depositAmount + 1 ether);

        // perform Deposit from depositor
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // record balance before cashout for the depositor via getter
        uint256 bal_before = c.balances(depositor);

        // bound cashOutAmt to a wide range including zero up to bal_before
        uint256 amt = cashOutAmt % (bal_before + 1);

        // perform CashOut as depositor
        vm.prank(depositor);
        // use try/catch only if external call could revert; here we just call
        c.CashOut(amt);

        // single assertion: after CashOut, the stored balance equals bal_before - amt
        // This property holds for the reference implementation for all inputs (when deposit branch executed),
        // but the mutant that caps deposit to MinDeposit will make bal_before smaller for some depositAmount > MinDeposit,
        // causing the equality to fail for some fuzz inputs. We assert via c.balances getter.
        assertTrue(c.balances(depositor) == bal_before - amt);
    }
}

