    // fuzz parameters: depositor address, deposit amount, cashout amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 cashAmt) public {
        // Keep depositor non-zero and depositAmt in a practical range
        vm.assume(depositor != address(0));
        // Ensure depositAmt > MinDeposit so Deposit's if-branch executes
        uint256 Min = c.MinDeposit();
        depositAmt = bound(depositAmt, Min + 1, type(uint256).max);
        // Fund depositor for the deposit and potential cashout
        vm.deal(depositor, depositAmt + 1 ether);

        // Record previous balance for depositor
        uint256 prevBal = c.balances(depositor);

        // depositor makes Deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // After deposit, expected balance in reference = prevBal + depositAmt
        uint256 afterDeposit = c.balances(depositor);

        // cashAmt should be <= afterDeposit to allow CashOut to proceed
        cashAmt = bound(cashAmt, 0, afterDeposit);

        bool ok;
        // depositor attempts cash out; catch revert to observe behavior
        vm.prank(depositor);
        try c.CashOut(cashAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After CashOut (successful or not), read stored balance
        uint256 finalBal = c.balances(depositor);

        // The general invariant we assert: if CashOut succeeded, finalBal == prevBal + depositAmt - cashAmt
        // The reference implementation satisfies this for all admissible inputs; the mutant that adds MinDeposit instead
        // of msg.value will violate it for some deposited amounts > MinDeposit.
        if (ok) {
            assertTrue(finalBal == prevBal + depositAmt - cashAmt);
        } else {
            // If CashOut reverted, still ensure balances unchanged from afterDeposit (CashOut's branch guarded by <=)
            // For the reference, when CashOut reverts, the stored balance must still equal afterDeposit.
            assertTrue(finalBal == afterDeposit);
        }
    }
}

