        uint256 prevBal = c.balances(depositor);

        // Perform deposit as depositor
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // After reference Deposit, expected balance = prevBal + depositAmt
        // We now choose cashAmt to be in [0, prevBal + depositAmt]
        uint256 maxCash = prevBal + depositAmt;
        cashAmt = bound(cashAmt, 0, maxCash);

        // Ensure depositor has at least 1 wei to receive refunds if any (not strictly necessary)
        // Perform CashOut as depositor; wrap in try/catch to capture revert behavior
        bool ok;
        try c.CashOut(cashAmt) {
            ok = true;
        } catch {
            ok = false;
