import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: sender address and amount to send
    function testFuzz_property(address sender, uint256 amount) public {
        // Keep domain wide but sensible: amount fits in balance and not absurd gas values
        // Ensure sender is not zero address for meaningful caller
        vm.assume(sender != address(0));
        // Bound amount to reasonable range up to 5 ether (keeps test efficient)
        amount = bound(amount, 0, 5 ether);

        // Ensure sender has funds to send
        vm.deal(sender, amount);

        // Record balance before
        uint256 before = c.balances(sender);

        // Perform Deposit as the sender with the fuzzed amount
        vm.prank(sender);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, the reference contract guarantees: if amount > MinDeposit then balances[sender] increased by amount
        // We read the contract's public getter to observe actual behavior. This single assertion encodes that rule.
        if (amount > c.MinDeposit()) {
            // If Deposit succeeded (no revert thrown), then balances must have increased by amount
            // If Deposit reverted, ok==false and the rule would be violated by the reference — but reference never reverts on Deposit, so ok should be true.
            // However to keep the assertion purely on c's public surface, we assert balances changed as expected.
            uint256 after = c.balances(sender);
            assertTrue(after == before + amount);
        } else {
            // When amount <= MinDeposit, Deposit is a no-op in reference: balances unchanged
            uint256 after = c.balances(sender);
            assertTrue(after == before);
        }
    }
}

